export const PRESENTING_STORYTELLING_ACTIVITIES = [
{n:1,type:"mcq",micro:"Tujuan presentasi",q:"Tujuan utama sebuah presentasi adalah...",options:["Menyampaikan satu pesan penting sehingga penonton memahaminya & mengingatnya","Menampilkan sebanyak mungkin informasi di layar sehingga penonton mendapat semua data","Membuktikan bahwa kamu tahu jauh lebih banyak daripada orang lain di ruangan"],answer:0,explain:"Presentasi yang berhasil diukur dari apa yang penonton bawa pulang, bukan dari banyaknya slide.",hint:"Satu pesan yang diingat, atau tumpukan informasi?"},
{n:2,type:"mcq",micro:"Satu pesan inti",q:"Sebelum menyusun presentasi, hal pertama yang perlu jelas:",options:["Berapa lama durasi presentasi yang tersedia","'Kalau penonton cuma ingat satu hal, apa itu?'","Warna latar slide yang paling disukai penonton"],answer:1,explain:"Satu kalimat pesan inti menjadi jangkar; semua bagian lain mendukungnya.",hint:"Pesan inti dulu, atau desain slide dulu?"},
{n:3,type:"mcq",micro:"Struktur dasar",q:"Struktur presentasi yang paling mudah diikuti:",options:["Langsung masuk ke detail teknis tanpa pembuka, jadi waktu tak terbuang untuk basa-basi","Semua poin disusun acak sesuai ingatan saat itu, lalu berhenti tanpa penutup","Pembuka (apa & kenapa penting) → isi (2-3 poin) → penutup (rangkuman + ajakan)"],answer:2,explain:"'Katakan apa yang akan kamu sampaikan, sampaikan, lalu katakan apa yang sudah kamu sampaikan.'",hint:"Pembuka-isi-penutup, atau acak?"},
{n:4,type:"mcq",micro:"Pembuka yang menarik",q:"Cara membuka presentasi agar penonton tertarik:",options:["Pertanyaan, cerita singkat, fakta mengejutkan, atau gambaran situasi nyata","'Emm, jadi... saya mau presentasi tentang... anu...' sambil menunduk dan memegang kertas","Membaca judul slide dengan nada datar sambil menghadap layar, lalu pindah slide"],answer:0,explain:"Beberapa kalimat pertama menentukan apakah penonton menyimak atau melamun.",hint:"Hook yang hidup, atau pembuka datar?"},
{n:5,type:"mcq",micro:"Slide sebagai pendukung",q:"Isi slide sebaiknya...",options:["Kosong sepenuhnya, jadi perhatian penonton tertuju padamu dan tidak terpecah","Poin singkat, gambar, atau angka kunci — kamu yang menjelaskan dengan kata-kata","Paragraf penuh yang kamu baca kata per kata dari awal sampai akhir tanpa menatap penonton"],answer:1,explain:"Slide adalah pengingat & alat bantu visual, bukan naskah. Penonton tidak bisa membaca & menyimak sekaligus.",hint:"Poin & visual, atau paragraf dibaca?"},
{n:6,type:"mcq",micro:"Cerita membuat melekat",q:"Menyisipkan cerita/contoh nyata dalam presentasi membantu karena...",options:["Membuang waktu, cerita tak berhubungan dengan data penelitianmu","Membuat presentasi terlihat tidak serius dan kurang ilmiah","Manusia mengingat cerita jauh lebih baik daripada daftar fakta"],answer:2,explain:"'Data meyakinkan pikiran, cerita menggerakkan hati.' Gabungan keduanya paling kuat.",hint:"Mudah diingat, atau buang waktu?"},
{n:7,type:"mcq",micro:"Bagian cerita",q:"Cerita sederhana biasanya punya bagian...",options:["Tokoh & situasi awal → ada masalah/perubahan → apa yang terjadi & pelajarannya","Hanya kesimpulan atau pelajarannya saja tanpa menceritakan kejadian yang mendahuluinya","Deskripsi acak tentang banyak hal tanpa urutan, tokoh, atau masalah yang jelas"],answer:0,explain:"Awal (kenalkan) → tengah (konflik/perubahan) → akhir (hasil & makna). Ini kerangka cerita paling dasar.",hint:"Awal-tengah-akhir, atau acak?"},
{n:8,type:"mcq",micro:"Kontak mata saat presentasi",q:"Saat presentasi, sebaiknya kamu...",options:["Menghadap slide dan membelakangi penonton, lalu membaca tulisan di layar dengan jelas","Menyapukan pandangan ke berbagai bagian penonton, bukan menatap layar/lantai terus","Menatap satu titik di bagian belakang ruangan sepanjang waktu tanpa menoleh ke penonton lain"],answer:1,explain:"Kontak mata menjangkau penonton membuat mereka merasa diajak bicara & membantu kamu membaca reaksi.",hint:"Menyapa penonton dengan pandangan, atau menatap layar?"},
{n:9,type:"order",micro:"Menyiapkan presentasi",q:"Urutkan langkah menyiapkan presentasi 5 menit.",items:["Tentukan satu pesan inti & siapa penontonnya","Susun kerangka: pembuka, 2-3 poin, penutup","Buat slide/alat bantu yang mendukung tiap bagian","Latihan lisan beberapa kali & cek durasi"],answer:[0,1,2,3],explain:"Pesan & penonton → kerangka → slide → latihan. Slide dibuat SETELAH isi jelas, bukan sebelumnya.",hint:"Apa yang harus jelas sebelum membuat slide?"},
{n:10,type:"mcq",micro:"Latihan",q:"Berlatih presentasi dengan suara keras (bukan hanya membaca dalam hati) membantu karena...",options:["Membuang tenaga; presentasi bisa langsung dibawakan tanpa latihan terlebih dahulu","Membuat presentasi terdengar dihafal dan kaku, lalu penonton merasa bosan sejak awal","Kamu menemukan kalimat yang sulit diucapkan, mengukur durasi asli, & mengurangi gugup saat tampil"],answer:2,explain:"Latihan lisan mengubah 'tahu isinya' menjadi 'bisa menyampaikannya'. Dua hal berbeda.",hint:"Menemukan masalah lebih awal, atau buang tenaga?"},
{n:11,type:"tf",micro:"Gugup itu wajar",q:"Benar atau Salah: Merasa gugup sebelum presentasi adalah hal normal yang dialami hampir semua orang, termasuk pembicara berpengalaman.",answer:true,explain:"Gugup menandakan kamu peduli. Latihan & napas dalam membantu mengelolanya, bukan menghilangkannya sepenuhnya.",hint:"Gugup = kamu payah, atau wajar dan bisa dikelola?"},
{n:12,type:"tf",micro:"Slide penuh teks",q:"Benar atau Salah: Semakin banyak teks di slide, semakin baik presentasimu karena penonton bisa membaca semuanya.",answer:false,explain:"Sebaliknya, slide penuh teks membuat penonton sibuk membaca & berhenti menyimakmu. Slide berisi poin singkat + kamu yang menjelaskan jauh lebih efektif.",hint:"Banyak teks = lebih baik?"},
{n:13,type:"mcq",micro:"Durasi & fokus",q:"Kalau waktumu 5 menit, sebaiknya...",options:["Pilih 2-3 poin penting & sampaikan dengan jelas; buang detail kecil","Masukkan 10 poin sekaligus dengan bicara cepat, lalu berharap semua tersampaikan","Bahas satu poin saja 5 menit penuh tanpa pembuka atau penutup yang jelas"],answer:0,explain:"Waktu terbatas memaksa memilih. Sedikit poin yang tersampaikan mengalahkan banyak poin yang berlomba.",hint:"Sedikit & jelas, atau banyak & cepat?"},
{n:14,type:"mcq",micro:"Penutup yang kuat",q:"Cara menutup presentasi:",options:["Berhenti mendadak di tengah kalimat tanpa penutup, lalu meninggalkan panggung begitu saja saat waktunya habis","Rangkum pesan inti dalam satu kalimat + ajakan/pertanyaan penutup + ucapan terima kasih","'Ya, udah gitu aja sih, kayaknya sudah cukup deh, nggak tahu lagi mau ngomong apa, sekian dulu.'"],answer:1,explain:"Penutup adalah 'oleh-oleh'. Penonton mengingat awal & akhir paling kuat.",hint:"Rangkuman + ajakan, atau berhenti mendadak?"},
{n:15,type:"mcq",micro:"Suara & tempo",q:"Saat presentasi di ruangan, dibanding mengobrol biasa, kamu perlu...",options:["Bicara lebih cepat dan pelan sekaligus untuk terdengar santai, bukan berpidato","Bergumam dengan suara rendah untuk terdengar santai dan akrab seperti mengobrol","Suara sedikit lebih kuat, tempo lebih tenang, & jeda setelah poin penting"],answer:2,explain:"Ruangan lebih besar butuh proyeksi suara lebih kuat & jeda yang jelas agar pesan sempat dicerna.",hint:"Lebih kuat + lebih tenang + jeda, atau cepat + pelan?"},
{n:16,type:"mcq",micro:"Menghadapi lupa di tengah",q:"Kamu lupa poin berikutnya saat presentasi. Yang bisa dilakukan:",options:["Berhenti sebentar, lihat catatan/slide, tarik napas, lalu lanjut — jeda singkat itu wajar","Panik lalu meminta maaf berkali-kali sambil berkata 'aduh maaf, aku lupa, maaf banget ya'","Berbicara ngawur apa saja yang terlintas, untuk mengisi jeda diam di depan penonton"],answer:0,explain:"Jeda singkat untuk melihat catatan hampir tidak terasa bagi penonton & jauh lebih baik daripada panik.",hint:"Jeda tenang + lihat catatan, atau panik / ngawur?"},
{n:17,type:"mcq",micro:"Menyapa penonton",q:"Membuka dengan menyebut 'kalian' & hal yang relevan bagi mereka ('kalian pasti pernah...') membuat...",options:["Tidak ada bedanya; isi presentasi tetap sama saja bagi penonton","Penonton merasa presentasi ini untuk mereka, bukan sekadar tugasmu","Presentasi terdengar sombong dan menggurui; terlalu banyak menyebut penonton"],answer:1,explain:"Presentasi yang bagus terasa seperti percakapan yang ditujukan ke penonton, bukan pembacaan naskah.",hint:"Terasa untuk penonton, atau sekadar tugas?"},
{n:18,type:"mcq",micro:"Alat bantu visual",q:"Grafik atau gambar dalam presentasi paling berguna bila...",options:["Rumit, penuh angka kecil, dan banyak garis untuk menunjukkan kamu bekerja keras","Hanya sebagai hiasan untuk memeriahkan slide, tanpa hubungan dengan isi yang dibahas","Sederhana, berlabel jelas, & langsung mendukung poin yang sedang kamu bahas"],answer:2,explain:"Satu grafik jelas yang menunjukkan satu hal mengalahkan tabel penuh yang tak terbaca.",hint:"Sederhana & mendukung poin, atau rumit / hiasan?"},
{n:19,type:"mcq",micro:"Menerima pertanyaan",q:"Saat sesi tanya jawab & kamu tidak tahu jawabannya:",options:["'Pertanyaan bagus. Aku belum tahu pasti, nanti aku cari & kabari.'","Mengarang jawaban dengan nada yakin untuk terlihat pintar dan tak diragukan","Mengabaikan pertanyaan itu dan langsung memanggil penanya lain"],answer:0,explain:"Mengakui tidak tahu dengan jujur lebih dihargai daripada jawaban ngawur yang bisa ketahuan.",hint:"Jujur + tawaran cari tahu, atau mengarang / abaikan?"},
{n:20,type:"open",micro:"Menyusun kerangka presentasi",q:"Kamu diminta presentasi 3 menit tentang 'kenapa perpustakaan sekolah perlu jam buka lebih panjang'. Tulis kerangka lengkap: pesan inti, pembuka, 2 poin isi, dan penutup. Jelaskan singkat pilihanmu.",explain:"Jawaban baik memuat: satu pesan inti yang jelas; pembuka yang menarik (pertanyaan/cerita/fakta) dan menyebut relevansi bagi penonton; dua poin isi yang berbeda dan saling melengkapi (mis. kebutuhan + kelayakan) dengan contoh konkret; penutup berisi rangkuman pesan inti + ajakan/pertanyaan; plus penjelasan singkat pilihan.",hint:"Pesan inti satu kalimat; pembuka yang melibatkan penonton; 2 poin berbeda + contoh; penutup rangkuman + ajakan konkret.",sample:"PESAN INTI: 'Menambah jam buka perpustakaan 1 jam setelah pulang sekolah akan membantu banyak siswa yang tidak bisa belajar tenang di rumah.' PEMBUKA (hook + kenapa penting): 'Coba angkat tangan siapa yang pernah nggak bisa ngerjain PR di rumah karena berisik atau nggak ada tempat. Buat sebagian teman kita, itu terjadi tiap hari.' POIN 1 (kebutuhan): banyak siswa tinggal di rumah yang ramai/sempit; perpustakaan adalah satu-satunya tempat belajar gratis dan tenang, tapi tutup tepat saat sekolah bubar. Contoh: seorang teman yang biasa belajar di lorong karena perpustakaan sudah tutup. POIN 2 (kelayakan): hanya perlu 1 jam tambahan, bisa dijaga bergiliran oleh guru piket atau siswa relawan; sekolah lain sudah melakukannya. PENUTUP (rangkuman + ajakan): 'Satu jam lebih lama, tempat belajar untuk puluhan siswa. Aku usul kita ajukan ini ke kepala sekolah lewat OSIS. Terima kasih.' Pilihan: aku pakai hook berupa pertanyaan yang melibatkan penonton, dua poin yang menjawab 'apakah perlu?' dan 'apakah bisa?', contoh nyata di poin 1 supaya melekat, dan penutup berisi ajakan konkret."},
{n:21,type:"classify",micro:"Slide baik vs buruk",q:"Kelompokkan tiap ciri slide ke 'Baik' atau 'Buruk'.",items:["3-5 poin singkat per slide","Paragraf 8 baris yang dibaca kata per kata","Satu grafik sederhana berlabel jelas","Latar ramai dengan tulisan kecil warna-warni"],groups:["Baik","Buruk"],answer:{"Baik":["3-5 poin singkat per slide","Satu grafik sederhana berlabel jelas"],"Buruk":["Paragraf 8 baris yang dibaca kata per kata","Latar ramai dengan tulisan kecil warna-warni"]},explain:"Slide baik: sedikit, jelas, mendukung. Slide buruk: penuh, kecil, ramai, jadi naskah.",hint:"Sedikit & jelas, atau penuh & ramai?"},
{n:22,type:"mcq",micro:"Mengenal audiens",q:"Sebelum menyusun presentasi, mengetahui 'siapa penontonnya' membantu menentukan...",options:["Tidak berpengaruh apa-apa; isi presentasi sama saja bagi semua kelompok pendengar yang hadir di ruangan itu, berapa pun usianya","Seberapa dasar penjelasan, contoh apa yang cocok, istilah apa yang perlu dijelaskan, & apa yang mereka pedulikan","Warna slide dan jenis huruf saja, yang paling terlihat oleh penonton di ruangan tersebut"],answer:1,explain:"Presentasi yang sama bisa terlalu dasar untuk satu kelompok & terlalu tinggi untuk kelompok lain.",hint:"Menyesuaikan isi ke penonton, atau abaikan?"},
{n:23,type:"mcq",micro:"Aturan 'satu ide per slide'",q:"Kenapa satu slide sebaiknya fokus pada satu ide?",options:["Menghemat kertas; slide yang lebih sedikit tak perlu dicetak untuk dibagikan kepada penonton","Membuat presentasi lebih panjang; setiap poin harus dijelaskan satu per satu kepada penonton","Penonton bisa menangkap satu hal dengan jelas sebelum lanjut, bukan bingung memilah beberapa hal sekaligus"],answer:2,explain:"Slide yang menjejalkan banyak ide memaksa penonton mengurai sendiri sambil menyimakmu.",hint:"Satu ide terserap jelas, atau banyak ide bertumpuk?"},
{n:24,type:"mcq",micro:"Cerita: konflik itu penting",q:"Cerita terasa hidup ketika ada...",options:["Ketegangan atau masalah yang harus diatasi, bukan hanya rangkaian kejadian datar","Sebanyak mungkin nama orang, tempat, dan tanggal yang disebutkan lengkap dan berurutan","Tak ada masalah di dalamnya; semuanya berjalan lancar dari awal sampai akhir tanpa hambatan"],answer:0,explain:"'Tokoh menghadapi rintangan X, mencoba Y, akhirnya Z' — konflik adalah jantung cerita.",hint:"Ada ketegangan, atau kejadian datar?"},
{n:25,type:"mcq",micro:"Menghubungkan cerita ke pesan",q:"Setelah bercerita dalam presentasi, penting untuk...",options:["Bercerita lagi cerita lain untuk menghibur penonton dan membuat mereka lupa waktu","Menautkannya ke pesan inti: 'Cerita tadi menunjukkan kenapa X penting'","Langsung pindah ke topik berikutnya tanpa menjelaskan maksud ceritanya"],answer:1,explain:"Cerita tanpa kaitan ke pesan hanya jadi hiburan yang terlupakan. Jembatani secara eksplisit.",hint:"Tautkan ke pesan, atau biarkan menggantung?"},
{n:26,type:"mcq",micro:"Jeda sebagai alat",q:"Jeda diam beberapa detik setelah kalimat penting berfungsi...",options:["Membuatmu terlihat lupa dan penonton jadi ragu padamu","Membuang waktu presentasi dan terburu-buru, jadi isi yang disampaikan sedikit","Memberi penonton waktu mencerna & menandai bahwa itu penting"],answer:2,explain:"Pembicara pemula takut jeda & mengisinya dengan 'eee'. Jeda yang percaya diri justru menguatkan pesan.",hint:"Menandai pentingnya + waktu mencerna, atau terlihat lupa?"},
{n:27,type:"tf",micro:"Menghafal kata per kata",q:"Benar atau Salah: Menghafal presentasi kata per kata biasanya membuat penyampaian terdengar kaku & berisiko total blank kalau satu kata terlewat.",answer:true,explain:"Lebih baik hafal ALUR & poin kunci, lalu sampaikan dengan kata-katamu sendiri tiap kali. Terdengar alami & lebih tahan gangguan.",hint:"Hafal kata per kata = alami & aman, atau kaku & rapuh?"},
{n:28,type:"tf",micro:"Gugup harus hilang total dulu?",q:"Benar atau Salah: Kamu sebaiknya menunda presentasi sampai rasa gugupmu benar-benar hilang sepenuhnya.",answer:false,explain:"Sebaliknya, rasa gugup jarang hilang total & itu tidak apa-apa. Latihan, napas dalam, dan mulai dengan bagian yang kamu kuasai membantu kamu tampil baik meski masih sedikit gugup.",hint:"Tunggu gugup hilang total, atau tampil sambil mengelolanya?"},
{n:29,type:"mcq",micro:"Bahasa tubuh saat tampil",q:"Bahasa tubuh yang mendukung presentasi:",options:["Berdiri tegak, kaki mantap, gestur tangan yang sesuai isi, wajah hidup","Bersandar ke meja, tangan di saku, menatap lantai","Gestur besar tak henti yang tidak nyambung dengan kata-kata"],answer:0,explain:"Tubuh yang tenang & terbuka menyampaikan 'aku siap'. Gestur sebaiknya melayani isi, bukan gelisah.",hint:"Tegak + gestur sesuai isi, atau bersandar / gestur gelisah?"},
{n:30,type:"order",micro:"Membangun sebuah cerita untuk presentasi",q:"Urutkan langkah menyusun cerita pendek untuk menguatkan poin presentasi.",items:["Pilih poin yang ingin dikuatkan dengan cerita","Ingat/pilih satu kejadian nyata & spesifik yang berkaitan","Ceritakan singkat: siapa, situasi, apa yang terjadi","Tautkan ke poin: 'Inilah kenapa...'"],answer:[0,1,2,3],explain:"Poin → kejadian spesifik → cerita singkat → jembatan ke poin. Cerita melayani pesan, bukan sebaliknya.",hint:"Apa yang ditentukan sebelum memilih ceritanya?"},
{n:31,type:"mcq",micro:"Menyesuaikan panjang",q:"Kalau saat latihan presentasimu 8 menit padahal jatahnya 5, sebaiknya...",options:["Lewati penutup untuk memberi waktu menjelaskan semua poin dengan detail yang lengkap","Pangkas: buang contoh yang mengulang, gabungkan poin yang mirip, potong pembuka yang bertele-tele","Bicara lebih cepat saat tampil, lalu berharap semua isi tetap tersampaikan dalam waktu singkat saja"],answer:1,explain:"Memangkas isi lebih baik daripada mempercepat bicara (yang membuat penonton ketinggalan) atau membuang penutup (bagian yang paling diingat).",hint:"Pangkas isi, atau percepat / buang penutup?"},
{n:32,type:"tf",micro:"Minta maaf berlebihan",q:"Benar atau Salah: Membuka presentasi dengan banyak permintaan maaf ('maaf saya nggak siap', 'maaf kalau jelek') membuat penonton lebih menghargai usahamu.",answer:false,explain:"Sebaliknya, permintaan maaf berlebihan menurunkan harapan penonton & membuatmu terlihat kurang yakin sebelum mulai. Cukup mulai dengan tenang & percaya diri.",hint:"Minta maaf banyak di awal = dihargai, atau menurunkan kesan?"},
{n:33,type:"mcq",micro:"Interaksi dengan penonton",q:"Cara sederhana melibatkan penonton dalam presentasi:",options:["Membaca slide tanpa henti dari awal sampai akhir, jadi penonton tak sempat bertanya atau mengobrol sedikit pun","Melarang penonton bertanya atau bicara sampai presentasi selesai, jadi mereka diam dan tertib","Pertanyaan singkat ('angkat tangan siapa yang pernah...'), meminta bayangan, atau contoh dari mereka"],answer:2,explain:"Interaksi kecil menjaga perhatian & membuat penonton merasa bagian dari presentasi.",hint:"Ajak berpartisipasi, atau monolog?"},
{n:34,type:"mcq",micro:"Nada bercerita",q:"Saat bercerita dalam presentasi, nada suara yang cocok:",options:["Sedikit lebih hidup & bervariasi mengikuti isi cerita (tegang, lega, lucu)","Datar dan monoton seperti membaca laporan keuangan, untuk terdengar serius","Berteriak sepanjang cerita, untuk menjaga penonton terus terjaga dan tidak mengantuk"],answer:0,explain:"Cerita hidup di variasi nada. Nada datar membunuh ketegangan & emosi cerita.",hint:"Nada bervariasi mengikuti cerita, atau datar?"},
{n:35,type:"mcq",micro:"Slide vs kamu",q:"Kalau penonton harus memilih antara memperhatikan slide atau memperhatikanmu, presentasi yang baik membuat...",options:["Keduanya padat dan bersaing merebut perhatian, sehingga penonton harus memilih","Slide cukup ringan sehingga perhatian utama tetap padamu & penjelasanmu","Slide begitu penuh tulisan sehingga kamu tak perlu berbicara dan cukup menunggu"],answer:1,explain:"Kamu adalah presentasi; slide hanya pendukung. Slide yang bersaing dengan pembicara melemahkan keduanya.",hint:"Slide ringan, fokus padamu — atau slide padat menggantikanmu?"},
{n:36,type:"mcq",micro:"Angka yang berarti",q:"Menyajikan angka '3.500' menjadi lebih bermakna bila...",options:["Ditampilkan sendirian di tengah slide tanpa penjelasan, dan penonton menafsirkan sendiri","Ditulis dengan banyak angka desimal untuk terlihat teliti, akurat, dan meyakinkan di depan penonton","Diberi pembanding atau konteks: 'setara isi 3 kelas penuh' atau 'naik 2x lipat dari tahun lalu'"],answer:2,explain:"Angka telanjang sulit dirasakan. Pembanding & konteks membuatnya 'terasa'.",hint:"Beri konteks/pembanding, atau angka telanjang?"},
{n:37,type:"tf",micro:"Latihan di depan orang",q:"Benar atau Salah: Berlatih presentasi di depan teman tidak berguna karena mereka bukan penonton sungguhan; lebih baik langsung tampil saja.",answer:false,explain:"Sebaliknya, penonton latihan menangkap bagian yang membingungkan yang kamu lewatkan karena sudah terlalu akrab dengan materinya.",hint:"Latihan di depan orang = membantu, atau buang waktu?"},
{n:38,type:"mcq",micro:"Membuka dengan pertanyaan",q:"Membuka dengan pertanyaan retoris yang bagus ('Pernahkah kamu ...?') berfungsi karena...",options:["Membuat penonton langsung berpikir & menghubungkan topik dengan pengalaman mereka","Membuang waktu pembukaan yang berharga; lebih baik langsung ke isi tanpa bertanya","Membuat penonton menjawab keras-keras bersamaan, lalu ruangan ramai dan sulit dikendalikan"],answer:0,explain:"Pertanyaan menarik penonton dari 'menonton' menjadi 'ikut memikirkan'.",hint:"Mengajak berpikir, atau buang waktu?"},
{n:39,type:"mcq",micro:"Menutup lingkaran",q:"Teknik 'callback' — merujuk kembali ke pembuka saat penutup ('Ingat pertanyaan di awal tadi? Sekarang kita punya jawabannya') — berguna karena...",options:["Membuat presentasi terasa diulang dan membosankan; penonton sudah mendengarnya tadi","Memberi rasa utuh & membantu penonton merasakan perjalanan presentasi selesai","Membingungkan penonton; mereka lupa sudah membahas apa, jadi ending tak nyambung"],answer:1,explain:"Menghubungkan akhir ke awal membuat presentasi terasa seperti satu cerita yang tuntas.",hint:"Rasa utuh, atau membingungkan?"},
{n:40,type:"open",micro:"Mengubah data jadi cerita",q:"Kamu punya data: 'Di kelas kami, 18 dari 30 siswa tidak sarapan sebelum sekolah.' Ubah penyajian data ini menjadi pembukaan presentasi yang lebih menggugah (boleh menambahkan detail masuk akal), lalu jelaskan teknik yang kamu pakai.",explain:"Jawaban baik: mengubah angka menjadi perbandingan/gambaran yang terasa, menaruh data dalam situasi konkret yang bisa dibayangkan, menambahkan satu detail manusia agar menggugah, dan mengarahkan ke pesan/tujuan presentasi — lalu menyebut teknik yang dipakai.",hint:"Ubah rasio jadi bahasa yang terasa, tempatkan dalam situasi konkret, beri satu 'wajah' manusia, arahkan ke tujuan.",sample:"Pembukaan: 'Bayangkan pelajaran jam pertama. Guru menjelaskan, tapi di deretan bangku, hampir dua dari setiap tiga anak sebenarnya sedang menahan lapar. Itu bukan bayangan — waktu kami tanya di kelas ini, 18 dari 30 orang mengaku berangkat tanpa sarapan. Salah satunya bercerita, ia sering pusing dan susah fokus sampai jam istirahat. Hari ini aku mau ngomongin kenapa ini penting dan apa yang bisa kita lakukan.' Teknik yang kupakai: (1) memulai dengan gambaran situasi konkret ('pelajaran jam pertama') supaya penonton membayangkan; (2) mengubah angka jadi perbandingan yang terasa ('dua dari setiap tiga anak') alih-alih '18 dari 30' yang abstrak; (3) menambahkan satu detail manusia (teman yang pusing dan susah fokus) supaya data punya wajah; (4) menutup pembuka dengan menyebut ke mana presentasi ini akan pergi."},
{n:41,type:"mcq",micro:"Skenario: presentasi tugas kelompok",q:"Kelompokmu presentasi & tiap orang pegang satu bagian. Agar tidak terasa terpotong-potong:",options:["Masing-masing menyiapkan bagiannya sendiri tanpa koordinasi, lalu bertemu langsung saat tampil di depan kelas, tanpa latihan","Satu orang berbicara membawakan semuanya sementara anggota lain hanya diam berdiri di belakang & tidak ikut berbicara","Sepakati pesan inti bersama, buat transisi antar bagian ('setelah tahu masalahnya, sekarang solusinya —'), & latihan sekali bersama"],answer:2,explain:"Presentasi kelompok yang baik terasa seperti satu cerita, bukan empat presentasi mini yang ditempel.",hint:"Pesan bersama + transisi + latihan bareng, atau sendiri-sendiri?"},
{n:42,type:"mcq",micro:"Skenario: waktu tiba-tiba dipangkas",q:"Kamu diberi tahu waktumu dipotong dari 5 jadi 2 menit tepat sebelum tampil. Sikap:",options:["Sampaikan pesan inti + satu poin terkuat + penutup singkat; lewati sisanya","Bicara sangat cepat mencoba memuat semua isi yang sudah disiapkan sebelumnya","Menolak tampil; waktu tak cukup untuk menyampaikan semuanya"],answer:0,explain:"Ketahui bagian mana yang paling penting sebelumnya, sehingga kamu bisa 'menciut' dengan tenang.",hint:"Inti + satu poin + penutup, atau semua dipercepat?"},
{n:43,type:"mcq",micro:"Skenario: penonton terlihat bosan",q:"Di tengah presentasi, banyak penonton menunduk ke HP. Respons yang bisa membantu:",options:["Marah pada penonton yang kurang memperhatikan, dengan harapan mereka kembali menyimak dengan tertib selama sisa presentasi","Ubah tempo, ajukan pertanyaan ke penonton, ceritakan contoh, atau lompat ke bagian yang lebih menarik","Terus membaca slide dengan nada sama sampai waktu habis, tanpa melihat reaksi penonton"],answer:1,explain:"Bahasa tubuh penonton adalah umpan balik langsung. Presenter yang baik menyesuaikan diri.",hint:"Ubah cara / libatkan mereka, atau lanjut sama saja / marah?"},
{n:44,type:"mcq",micro:"Skenario: alat gagal",q:"Proyektor mati di tengah presentasi. Sikap yang tenang:",options:["Panik lalu berhenti dan meminta semua menunggu sampai proyektor menyala kembali tanpa melanjutkan sedikit pun","Menyalahkan panitia keras-keras di depan penonton, menuduh tak menyiapkan peralatan dengan benar","'Sambil menunggu diperbaiki, aku lanjut tanpa slide — intinya begini...' — kamu tetap tahu isinya"],answer:2,explain:"Karena kamu adalah presentasi (bukan slide), kamu bisa lanjut. Ini alasan lain untuk tidak bergantung penuh pada slide.",hint:"Lanjut tanpa slide, atau panik / menyalahkan?"},
{n:45,type:"order",micro:"Menjalankan sesi tanya jawab",q:"Urutkan cara menangani pertanyaan dari penonton.",items:["Dengarkan pertanyaan sampai selesai","Ulangi/parafrasekan singkat agar semua penonton dengar & kamu paham","Jawab sejelas mungkin; kalau tidak tahu, akui & tawarkan mencari tahu","Cek: 'Sudah menjawab pertanyaanmu?'"],answer:[0,1,2,3],explain:"Dengar → ulangi → jawab jujur → konfirmasi. Mengulang pertanyaan membantu seluruh ruangan mengikuti.",hint:"Apa yang dilakukan sebelum menjawab?"},
{n:46,type:"mcq",micro:"Skenario: bercerita yang terlalu panjang",q:"Ceritamu dalam presentasi mulai melebar & memakan waktu. Yang sebaiknya:",options:["Latih cerita agar ringkas — buang detail yang tidak mengubah maknanya, langsung ke inti & pelajaran","Ceritakan semua detail sampai selesai karena 'biar lengkap' dan penonton harus tahu latar belakangnya","Berhenti bercerita di tengah jalan tanpa penutup, lalu langsung pindah ke slide berikutnya"],answer:0,explain:"Cerita yang kuat itu padat. Tiap detail harus 'membayar sewanya' dengan menambah makna.",hint:"Padat & sampai inti, atau semua detail?"},
{n:47,type:"mcq",micro:"Skenario: presentasi online",q:"Presentasi lewat video call, agar tetap menarik:",options:["Bicara panjang tanpa jeda atau interaksi sambil menatap layarmu sendiri, bukan lensa kamera, dan slide dipenuhi tulisan","Nyalakan kamera, tatap lensa (bukan wajahmu di layar), suara jelas, slide sederhana, sesekali panggil nama peserta untuk melibatkan","Matikan kamera lalu bacakan naskah dengan nada datar dari awal sampai akhir tanpa memperhatikan reaksi peserta"],answer:1,explain:"Di online, perhatian lebih mudah bocor. Kontak 'mata' lewat lensa & interaksi jadi lebih penting.",hint:"Kamera nyala + tatap lensa + libatkan, atau kamera mati + monolog?"},
{n:48,type:"mcq",micro:"Skenario: pertanyaan yang menyerang",q:"Seseorang bertanya dengan nada menyerang & meremehkan. Respons yang menjaga ketenangan:",options:["Membalas dengan nada menyerang yang sama kerasnya, untuk menunjukkan kamu tak bisa diremehkan","Diam dan tidak menjawab, lalu memanggil penanya berikutnya seolah tak ada yang bertanya tadi","Tetap tenang, tanggapi bagian isi yang valid, abaikan nada: 'Poin bagus soal biaya. Perkiraan kami begini...'"],answer:2,explain:"Menjawab isi dengan tenang membuatmu terlihat menguasai & tidak terpancing. Nada menyerang si penanya jadi sorotan, bukan kamu.",hint:"Jawab isi dengan tenang, atau balas menyerang / diam?"},
{n:49,type:"mcq",micro:"Skenario: latihan menghadapi gugup",q:"Cara mengelola gugup sebelum naik panggung:",options:["Latihan cukup, datang lebih awal untuk kenal ruangan, tarik napas panjang beberapa kali, mulai dengan bagian yang paling kamu kuasai","Menghindari latihan, dengan harapan penampilan terasa natural dan tidak kaku saat naik ke panggung, dan datang tepat waktu","Minum kopi banyak-banyak sebelum tampil untuk merasa segar dan bersemangat, bagaimanapun efeknya bagi tubuhmu"],answer:0,explain:"Gugup berkurang dengan persiapan & keakraban. Napas panjang menenangkan tubuh; pembuka yang dikuasai membangun momentum.",hint:"Latihan + kenal ruangan + napas, atau hindari latihan?"},
{n:50,type:"open",micro:"Merancang presentasi 5 menit",q:"Kamu akan presentasi 5 menit untuk mengusulkan kegiatan 'hari berbagi buku' di sekolah. Rancang: pesan inti, pembuka (dengan hook), 3 poin isi (masing-masing singkat), 1 tempat untuk cerita/contoh, penutup dengan ajakan, dan 1 hal yang akan kamu latih agar penyampaiannya kuat.",explain:"Jawaban baik memuat semua komponen yang diminta: pesan inti satu kalimat; pembuka dengan hook yang melibatkan penonton; 3 poin isi singkat dan berbeda; satu cerita/contoh nyata yang mendukung pesan; penutup dengan rangkuman + ajakan konkret; dan satu aspek penyampaian spesifik yang akan dilatih (mis. transisi, jeda, kontak mata, tempo).",hint:"Susun semua bagian; pastikan 3 poin berbeda, cerita mendukung pesan, penutup punya ajakan konkret, dan sebut latihan yang spesifik.",sample:"PESAN INTI: 'Hari berbagi buku sekali per semester bisa membuat ratusan buku bagus berpindah tangan tanpa biaya, dan menumbuhkan kebiasaan membaca.' PEMBUKA (hook): 'Di rumah kalian, ada berapa buku bagus yang sudah selesai dibaca dan sekarang cuma jadi penghuni rak? Sekarang kalikan itu dengan jumlah siswa di sekolah ini.' POIN 1: cara kerjanya sederhana — tiap siswa membawa 1-3 buku layak, ditata per kategori di aula, lalu semua boleh mengambil sejumlah yang sama. POIN 2: manfaatnya — akses buku gratis bagi yang tidak mampu beli, ruang bertukar rekomendasi, dan mengurangi buku menganggur. POIN 3: kebutuhannya kecil — satu hari, aula, beberapa meja, dan panitia dari OSIS. CERITA/CONTOH (di antara poin 1 dan 2): 'Tahun lalu sepupuku ikut acara serupa di sekolahnya dan pulang membawa novel yang sekarang jadi favoritnya — buku yang mungkin tidak akan pernah ia beli sendiri.' PENUTUP (ajakan): 'Bayangkan seribu buku berpindah ke tangan yang akan benar-benar membacanya, dalam satu hari, tanpa biaya. Aku usul OSIS bikin panitia kecil bulan ini. Terima kasih.' YANG AKAN KULATIH: transisi antar poin dan jeda setelah kalimat penutup tiap poin, supaya tidak terburu-buru dan penonton sempat mencerna; aku akan latihan lisan 3 kali dengan timer."},
{n:51,type:"mcq",micro:"Skenario: penonton beragam usia",q:"Presentasi ke campuran siswa & orang tua. Agar dua-duanya paham:",options:["Pakai bahasa yang sangat formal & rumit penuh istilah ilmiah, untuk terdengar meyakinkan bagi orang tua & murid","Pakai bahasa yang jelas untuk semua, jelaskan istilah, beri contoh yang relevan bagi kedua kelompok","Pakai bahasa gaul remaja sepenuhnya dengan banyak singkatan, & orang tua dibiarkan menyesuaikan sendiri"],answer:1,explain:"Audiens beragam menuntut bahasa yang bisa diakses semua & contoh yang menjangkau tiap kelompok.",hint:"Bahasa jelas untuk semua + contoh menjangkau, atau satu gaya sempit?"},
{n:52,type:"tf",micro:"Presentasi = percakapan terarah",q:"Benar atau Salah: Presentasi yang baik terasa lebih seperti berbicara KEPADA penonton daripada membacakan naskah DI HADAPAN mereka.",answer:true,explain:"Kontak mata, nada percakapan, & bahasa yang menyapa ('kalian') membuat perbedaan besar dalam keterhubungan.",hint:"Bicara kepada penonton, atau membaca di hadapan mereka?"},
{n:53,type:"mcq",micro:"Skenario: catatan kecil",q:"Membawa kartu catatan berisi poin kunci (bukan naskah penuh) saat presentasi...",options:["Tanda kamu tidak siap dan sebaiknya dihindari; presenter baik harus hafal di luar kepala","Berarti harus dibaca kata per kata dari awal sampai akhir tanpa mengangkat kepala menatap penonton","Wajar & membantu — kamu bisa melirik untuk memastikan alur tanpa membaca semuanya"],answer:2,explain:"Kartu poin kunci adalah jaring pengaman yang membebaskanmu dari rasa takut lupa, tanpa membuatmu membaca.",hint:"Kartu poin kunci = membantu, atau tanda tidak siap?"},
{n:54,type:"mcq",micro:"Skenario: bercerita tentang kegagalan",q:"Menceritakan sebuah kegagalan/kesalahan dalam presentasi (lalu pelajaran darinya) bisa efektif karena...",options:["Terasa jujur & manusiawi, membuat penonton lebih terhubung, & pelajarannya jadi kuat","Membuatmu terlihat tidak kompeten, jadi penonton tak lagi percaya pada pesan intimu di depan banyak orang","Sebaiknya dihindari; penonton hanya ingin kisah sukses dan tak peduli kesalahan"],answer:0,explain:"Cerita 'aku pernah salah, lalu belajar X' sering lebih menyentuh & meyakinkan daripada cerita sukses mulus.",hint:"Jujur & terhubung, atau selalu membuat terlihat buruk?"},
{n:55,type:"mcq",micro:"Skenario: transisi antar bagian",q:"Kalimat transisi yang baik antar bagian presentasi:",options:["'Emm, terus... apa lagi ya... oh iya, lalu... anu, kita lanjut saja ke yang berikutnya.'","'Setelah kita lihat kenapa ini masalah, sekarang mari bahas apa yang bisa kita lakukan.'","(langsung mengganti slide berikutnya tanpa kata penghubung, lalu mulai bicara topik baru)"],answer:1,explain:"Transisi adalah rambu jalan: menutup bagian lama, mengumumkan bagian baru, menjaga penonton tidak tersesat.",hint:"Kalimat penghubung yang jelas, atau lompatan tanpa kata?"},
{n:56,type:"mcq",micro:"Skenario: menghadapi penonton yang lebih ahli",q:"Kamu presentasi ke orang yang lebih tahu tentang topikmu. Sikap:",options:["Membatalkan presentasi, merasa tidak pantas berbicara di depan orang-orang yang jauh lebih paham darimu","Berpura-pura tahu lebih banyak daripada mereka & menjawab semua pertanyaan dengan nada yakin walaupun kamu belum paham betul di depan semua orang","Tetap sampaikan poinmu dengan percaya diri & jujur soal batas pengetahuanmu; anggap pertanyaan mereka sebagai kesempatan belajar"],answer:2,explain:"Kamu tetap punya sudut pandang & kerja yang layak disampaikan. Kejujuran soal batas justru membangun kredibilitas.",hint:"Percaya diri + jujur soal batas, atau batal / berpura-pura?"},
{n:57,type:"tf",micro:"Slide bukan pengganti latihan",q:"Benar atau Salah: Kalau slide-mu sudah bagus & lengkap, kamu tidak perlu berlatih menyampaikannya karena hasilnya akan sama saja.",answer:false,explain:"Sebaliknya, dua presenter dengan slide sama bisa memberi kesan sangat berbeda. Yang membuat presentasi hidup adalah cara menyampaikannya: suara, tempo, kontak mata, energi.",hint:"Slide bagus cukup, atau penyampaian tetap menentukan?"},
{n:58,type:"mcq",micro:"Skenario: mengelola waktu saat tampil",q:"Cara menjaga presentasi tetap sesuai waktu saat tampil:",options:["Tandai di catatan 'menit ke berapa harus sampai di mana', lirik jam sesekali, siapkan bagian yang bisa dipangkas bila mepet","Tidak memperhatikan waktu, fokus pada isi, dan berharap waktu cukup untuk semua yang ingin kamu sampaikan nanti","Berhenti mendadak di tengah kalimat begitu waktu habis, lalu turun dari panggung tanpa rangkuman atau ucapan penutup apa pun"],answer:0,explain:"Kesadaran waktu ('di menit 3 aku harus mulai penutup') mencegah kehabisan waktu sebelum penutup.",hint:"Tandai target waktu + siapkan pangkasan, atau abaikan waktu?"},
{n:59,type:"mcq",micro:"Skenario: latihan umpan balik",q:"Setelah latihan di depan teman, pertanyaan yang menghasilkan umpan balik berguna:",options:["(tidak meminta umpan balik, takut mendengar kritik dari teman sekelas ataupun guru)","'Bagian mana yang membingungkan? Kapan perhatianmu hilang? Apa satu hal yang paling perlu kuperbaiki?'","'Bagus nggak? Kalau bagus aku lanjut, kalau jelek aku nggak mau dengar penjelasannya ya.'"],answer:1,explain:"Pertanyaan spesifik menghasilkan jawaban yang bisa dipakai. 'Bagus nggak' mengundang 'bagus kok' yang kosong.",hint:"Pertanyaan spesifik, atau 'bagus nggak'?"},
{n:60,type:"open",micro:"Skenario menyeluruh: menyelamatkan presentasi",q:"Saat presentasi kelompok, temanmu yang giliran pertama tiba-tiba sakit dan tidak bisa hadir. Kamu harus membawakan bagiannya + bagianmu sendiri, total 6 menit, dengan persiapan 10 menit. Rancang langkah-langkahmu.",explain:"Jawaban baik: mengelola waktu persiapan dengan tenang; menyaring bagian teman ke pesan inti + poin terpenting saja (bukan semua); membuat kerangka gabungan dengan transisi jelas; latihan lisan + cek durasi + siapkan pangkasan; membuka dengan mengakui situasi singkat; jujur soal detail yang tidak dikuasai; memprioritaskan kejelasan pesan inti di atas kelengkapan.",hint:"Saring ke inti + poin utama, buat kerangka gabungan bertransisi, latih + cek waktu, akui situasi singkat, utamakan kejelasan.",sample:"(1) Tenangkan diri dan pakai 10 menit ini seefisien mungkin, jangan panik. (2) Baca cepat catatan bagian temanku, tandai HANYA pesan inti dan 2 poin terpentingnya — aku tidak perlu menyampaikan semuanya, cukup yang penting. (3) Tulis kerangka gabungan di satu kartu: pembuka singkat (sebut bahwa aku membawakan dua bagian karena teman berhalangan) → pesan inti bagian 1 + 2 poin → transisi ('itu masalahnya, sekarang bagianku soal solusinya') → bagianku seperti biasa → penutup gabungan. (4) Latih lisan sekali sambil melihat jam; kalau lewat 6 menit, potong contoh yang mengulang. (5) Saat tampil: buka dengan tenang, akui situasinya sekali ('Rekan kami berhalangan, jadi saya bawakan bagiannya juga'), lalu jalankan kerangka. Kalau ada detail bagian teman yang aku tidak yakin, aku sampaikan garis besarnya saja dan bilang 'detailnya bisa ditanyakan saat sesi tanya jawab, akan kami lengkapi'. (6) Fokus ke pesan inti, bukan kesempurnaan — penonton lebih menghargai penyampaian yang jelas dan tenang daripada semua detail yang berlomba."},
{n:61,type:"mcq",micro:"Mengapa 'satu pesan' penting",q:"Mengapa presentasi dengan satu pesan inti yang jelas lebih efektif daripada yang mencoba menyampaikan sepuluh hal?",options:["Sepuluh hal terlalu sulit disiapkan, jadi lebih mudah mempersiapkan satu pesan, bukan alasan lain tentang penonton","Penonton umumnya malas & tidak mau mendengarkan banyak hal, jadi mereka sebaiknya hanya diberi sedikit saja","Memori penonton terbatas; mereka akan lupa sebagian besar, jadi lebih baik memastikan satu hal yang penting benar-benar melekat"],answer:2,explain:"Kamu tidak bisa mengontrol semua yang penonton ingat, tapi kamu bisa memperbesar peluang mereka mengingat satu hal.",hint:"Memori terbatas, jadi fokuskan — atau penonton malas?"},
{n:62,type:"mcq",micro:"Mengapa cerita melekat",q:"Mengapa cerita lebih mudah diingat daripada daftar poin?",options:["Cerita punya urutan sebab-akibat, tokoh, & emosi yang membuat otak kita 'menyimpannya' sebagai pengalaman","Cerita lebih pendek daripada daftar poin, sehingga penonton tak sempat lupa yang kamu sampaikan","Poin-poin membosankan dengan sendirinya sehingga orang tak bisa mengingat apa-apa dari daftar itu"],answer:0,explain:"Otak berevolusi memahami dunia lewat cerita. Fakta yang tertanam dalam cerita ikut terbawa & bertahan.",hint:"Struktur + tokoh + emosi, atau sekadar lebih pendek?"},
{n:63,type:"tf",micro:"Awal & akhir paling diingat",q:"Benar atau Salah: Penonton cenderung paling mengingat bagian pembuka & penutup presentasi, jadi kedua bagian itu layak disiapkan paling matang.",answer:true,explain:"Kesan pertama menentukan apakah mereka menyimak; kesan terakhir menentukan apa yang mereka bawa pulang.",hint:"Awal & akhir paling diingat, atau bagian tengah?"},
{n:64,type:"mcq",micro:"Menilai presentasi",q:"Tanda sebuah presentasi berhasil:",options:["Presenternya berbicara paling lama dibandingkan semua pembicara lain, jadi penonton menerima informasi paling banyak","Penonton bisa menyebutkan pesan intinya & satu hal yang akan mereka lakukan/pikirkan, bukan sekadar 'wah, slidenya bagus'","Slidenya memiliki animasi paling banyak & desain paling mewah, lalu penonton terus membicarakannya setelah presentasi selesai"],answer:1,explain:"Ujian sejati: apa yang tertinggal di kepala penonton setelah keluar ruangan?",hint:"Pesan tertangkap & ada dampak, atau slide keren?"},
{n:65,type:"mcq",micro:"Mengapa membaca slide gagal",q:"Mengapa membacakan slide kata per kata membuat presentasi lemah?",options:["Membaca slide dengan keras itu sopan dan membantu penonton yang kurang bisa membaca atau duduk jauh","Slide yang dibacakan biasanya salah atau tak akurat, jadi lebih baik tak dibaca penonton","Penonton bisa membaca lebih cepat daripada kamu bicara, jadi mereka bosan & merasa kamu tidak menambah nilai"],answer:2,explain:"Kalau slide sudah berisi semuanya & kamu hanya membacanya, untuk apa kamu ada di sana?",hint:"Penonton membaca lebih cepat & bosan, atau membaca itu sopan?"},
{n:66,type:"tf",micro:"Gugup selalu terlihat penonton?",q:"Benar atau Salah: Rasa gugup yang kamu rasakan di dalam biasanya jauh lebih terlihat oleh penonton daripada kenyataannya.",answer:false,explain:"Sebaliknya, penonton biasanya tidak menyadari sebagian besar gugupmu — jantung berdebar & tangan dingin tidak terlihat. Menyadari ini bisa mengurangi kecemasan.",hint:"Gugupmu sangat kelihatan, atau lebih tersembunyi dari yang kamu kira?"},
{n:67,type:"mcq",micro:"Menyesuaikan cerita ke pesan",q:"Kalau sebuah cerita menarik tapi tidak benar-benar mendukung pesan intimu, sebaiknya...",options:["Buang atau ganti — cerita harus melayani pesan, bukan sekadar menghibur","Tetap pakai; ceritanya lucu dan disukai penonton meski di luar topik pembicaraan","Tetap pakai lalu ubah pesan intimu hingga cocok dengan ceritanya"],answer:0,explain:"Cerita yang tidak nyambung membuang waktu & mengaburkan fokus. Setiap bagian harus 'membayar sewa'.",hint:"Cerita melayani pesan, atau hiburan tanpa kaitan?"},
{n:68,type:"mcq",micro:"Kekuatan jeda",q:"Mengapa pembicara berpengalaman berani memakai jeda diam yang cukup panjang?",options:["Jeda tidak punya fungsi; hanya membuat presentasi terasa lambat dan berlarut","Jeda menarik perhatian kembali, memberi bobot pada kalimat, & menunjukkan kepercayaan diri","Mereka lupa teks, jadi berhenti sebentar untuk mengingat naskah kembali"],answer:1,explain:"Ruang kosong dalam bicara sama pentingnya dengan ruang kosong dalam desain. Jeda menekankan.",hint:"Menekankan & menarik perhatian, atau tanda lupa?"},
{n:69,type:"mcq",micro:"Menilai slide yang 'cantik tapi kosong'",q:"Slide dengan animasi & desain mewah tapi isinya tidak jelas...",options:["Lebih baik daripada slide sederhana; penonton menyukai tampilan meriah dan penuh gerak","Menjamin presentasi sukses; tampilan mewah membuat penonton otomatis percaya pada isinya yang disampaikan","Bisa mengalihkan perhatian dari pesan & membuat penonton mengagumi bentuk tanpa menangkap isi"],answer:2,explain:"Desain melayani kejelasan. Kalau desain bersaing dengan pesan, pesan yang kalah.",hint:"Bisa mengalihkan dari pesan, atau selalu lebih baik?"},
{n:70,type:"order",micro:"Dari materi mentah ke presentasi",q:"Urutkan proses mengubah setumpuk materi menjadi presentasi yang fokus.",items:["Tanya: apa satu hal terpenting yang penonton harus tahu/lakukan?","Pilih 2-3 poin yang paling mendukung hal itu; sisihkan sisanya","Cari satu cerita/contoh/data yang membuat poin terkuat terasa nyata","Susun pembuka & penutup yang menonjolkan pesan inti"],answer:[0,1,2,3],explain:"Pesan inti → pilih poin pendukung → konkretkan → bingkai dengan pembuka-penutup. Memilih, bukan menumpuk.",hint:"Apa yang ditentukan pertama sebelum memilih poin?"},
{n:71,type:"mcq",micro:"Presentasi & kepercayaan",q:"Mengapa kejujuran (mengakui ketidakpastian, batas data, atau kesalahan) menguatkan presentasi?",options:["Penonton lebih memercayai pembicara yang tampak jujur daripada yang mengklaim tahu segalanya dengan sempurna","Kejujuran membuat pembicara terlihat lemah dan kurang berwibawa di depan penonton yang menunggu kepastian dari awal","Penonton tak peduli pada kejujuran pembicara; mereka hanya memperhatikan kepandaian dan gaya bicaranya"],answer:0,explain:"'Data kami terbatas pada 30 responden, jadi ini gambaran awal' lebih kredibel daripada klaim mutlak.",hint:"Jujur membangun kepercayaan, atau melemahkan?"},
{n:72,type:"tf",micro:"Latihan mengurangi beban mental",q:"Benar atau Salah: Terlalu banyak berlatih presentasi membuat penyampaianmu pasti terdengar kaku & seperti hafalan, jadi sebaiknya latihan cukup sekali saja.",answer:false,explain:"Sebaliknya, latihan (mengulang alur & poin, bukan menghafal kata per kata) memindahkan isi ke 'otomatis', membebaskan perhatianmu untuk membaca ruangan & terhubung dengan penonton.",hint:"Latihan membebaskan perhatian untuk penonton, atau membuat kaku?"},
{n:73,type:"mcq",micro:"Menilai keterlibatan penonton",q:"Cara membaca apakah penonton mengikuti:",options:["Tanya 'kalian ngerti kan?' cepat lalu abaikan jawabannya dan lanjut ke slide berikutnya","Perhatikan kontak mata mereka, anggukan, ekspresi wajah, & apakah HP mulai keluar","Anggap mereka mengikuti setiap kalimatmu; presentasi yang baik tak membuat bosan"],answer:1,explain:"Penonton memberi umpan balik non-verbal terus-menerus. Presenter yang baik membacanya & menyesuaikan diri.",hint:"Baca sinyal mereka, atau berasumsi?"},
{n:74,type:"mcq",micro:"Struktur untuk membujuk",q:"Untuk presentasi yang bertujuan mengajak orang bertindak, struktur yang efektif:",options:["Langsung minta orang bertindak tanpa menjelaskan mengapa itu penting, jadi presentasi singkat & cepat sampai ke intinya","Hanya menjelaskan masalah dengan panjang lebar tanpa menawarkan solusi, lalu penonton menyimpulkan sendiri apa yang harus dilakukan","Tunjukkan masalah (yang penonton pedulikan) → dampaknya → solusi yang kamu usulkan → langkah konkret yang bisa mereka ambil"],answer:2,explain:"Orang bertindak ketika mereka merasakan masalahnya & melihat jalan keluar yang jelas & bisa dijalankan.",hint:"Masalah-dampak-solusi-langkah, atau langsung menyuruh?"},
{n:75,type:"tf",micro:"Penonton ingin presenter berhasil",q:"Benar atau Salah: Kebanyakan penonton sebenarnya ingin presenter berhasil & tidak menikmati melihat orang gagal, jadi mereka cenderung memaafkan kegugupan kecil.",answer:true,explain:"Membayangkan penonton sebagai 'pendukung yang berharap kamu sukses' (bukan hakim yang mencari kesalahan) menurunkan kecemasan.",hint:"Penonton musuh yang menghakimi, atau umumnya mendukung?"},
{n:76,type:"mcq",micro:"Menilai panjang cerita",q:"Berapa porsi cerita yang pas dalam presentasi 5 menit?",options:["Cukup untuk membuat satu poin terasa nyata (mis. 30-60 detik), bukan menghabiskan separuh waktu","Sebanyak mungkin, hampir seluruh waktu; cerita lebih penting daripada isi dan pesan inti","Nol, tak perlu ada cerita; cerita hanya membuang waktu dan tak berguna bagi penonton dewasa yang sibuk"],answer:0,explain:"Cerita adalah bumbu yang menguatkan, bukan hidangan utama yang menggantikan isi.",hint:"Secukupnya untuk menguatkan poin, atau habiskan separuh waktu?"},
{n:77,type:"mcq",micro:"Mengapa transisi penting",q:"Tanpa kalimat transisi antar bagian, penonton sering...",options:["Menghafal lebih baik; penonton tak perlu melihat petunjuk struktur di layar","Bingung apakah ini poin baru atau lanjutan, & kehilangan peta keseluruhan presentasi","Lebih fokus; penonton hanya perlu mendengar tanpa tahu urutan presentasi ini"],answer:1,explain:"Transisi adalah 'jahitan' yang membuat bagian-bagian terasa satu kesatuan.",hint:"Bingung & kehilangan peta, atau lebih fokus?"},
{n:78,type:"mcq",micro:"Presentasi sebagai keterampilan",q:"Kemampuan presentasi & bercerita...",options:["Adalah bakat bawaan sejak lahir; kalau tidak punya, latihan sebanyak apa saja tetap percuma dan tak mengubah apa-apa, jadi lebih baik ditinggalkan","Hanya bisa dipelajari lewat kursus mahal dengan pelatih profesional, jadi tidak mungkin dilatih sendiri oleh siswa biasa","Bisa dilatih oleh siapa saja lewat persiapan, latihan, umpan balik, & pengulangan — bukan bakat yang dimiliki segelintir orang"],answer:2,explain:"Hampir semua pembicara yang tampak 'alami' sebenarnya telah berlatih banyak. Kamu bisa membaik dengan latihan sadar.",hint:"Bisa dilatih siapa saja, atau bakat segelintir?"},
{n:79,type:"mcq",micro:"Menilai 'kesempurnaan' vs koneksi",q:"Presentasi yang sedikit tersendat tapi tulus & terhubung dengan penonton dibanding presentasi mulus tapi dingin & dibaca:",options:["Yang tulus & terhubung sering lebih berkesan & lebih efektif menyampaikan pesan","Yang mulus tanpa cela lebih berkesan; penonton menghargai kesempurnaan","Keduanya sama saja; penonton tidak membedakan mulus dan tulus"],answer:0,explain:"Penonton memaafkan ketidaksempurnaan kecil, tapi sulit terhubung dengan pembacaan yang tanpa jiwa.",hint:"Tulus & terhubung, atau mulus & dingin?"},
{n:80,type:"open",micro:"Menganalisis dua presenter",q:"Presenter A: slide penuh teks, membaca kata per kata sambil menunduk, tanpa contoh, selesai tepat waktu. Presenter B: slide berisi poin & satu grafik, bicara dengan kata-kata sendiri sambil menatap penonton, menyisipkan satu cerita singkat, sedikit lewat waktu. Jelaskan siapa yang kemungkinan besar lebih efektif menyampaikan pesan & mengapa (minimal 3 alasan), lalu sebut 1 hal yang bisa diperbaiki dari masing-masing.",explain:"Jawaban baik memilih Presenter B dan memberi minimal 3 alasan (koneksi/kontak mata & bahasa sendiri, slide ringan menjaga fokus pada pembicara, cerita membantu memori) lalu menyebut satu perbaikan konkret untuk A (pangkas teks + latih penyampaian + kontak mata) dan satu untuk B (kelola durasi / pangkas contoh).",hint:"Bandingkan koneksi, peran slide, dan daya ingat; lalu satu perbaikan realistis untuk tiap presenter.",sample:"Presenter B kemungkinan besar lebih efektif menyampaikan pesan. Alasan: (1) Ia berbicara dengan kata-kata sendiri sambil menatap penonton, jadi terasa seperti percakapan dan penonton merasa diajak bicara, sementara A membaca sambil menunduk sehingga tidak ada koneksi. (2) Slide B ringan (poin + grafik) sehingga perhatian penonton tetap pada penjelasannya; slide A yang penuh teks membuat penonton sibuk membaca dan bosan karena bisa membaca lebih cepat daripada A bicara. (3) B menyisipkan cerita singkat yang membuat pesan lebih mudah diingat, sedangkan A hanya menyajikan informasi datar tanpa 'pengait' memori. Yang bisa diperbaiki: Presenter A sebaiknya memangkas teks slide jadi poin dan berlatih menyampaikan dengan kata-kata sendiri sambil menatap penonton. Presenter B sebaiknya berlatih durasi lebih ketat (mis. memangkas satu contoh) supaya tidak melewati waktu, karena melebihi waktu bisa mengganggu jadwal dan penutup terburu-buru."},
{n:81,type:"mcq",micro:"Kasus: presentasi topik yang berat/sensitif",q:"Kamu presentasi tentang topik menyedihkan (mis. dampak bencana). Nada & pendekatan:",options:["Bercanda sepanjang presentasi untuk menjaga suasana tetap ringan dan penonton tidak ikut merasa sedih mendengar topik tersebut di depan semua orang","Serius & menghormati, fakta yang jelas, satu cerita manusia yang sopan (bukan mengeksploitasi), fokus pada apa yang bisa dilakukan","Berlebihan dalam bersikap dramatis & membuat penonton merasa bersalah dengan cerita-cerita yang sangat menyayat hati"],answer:1,explain:"Topik berat butuh nada yang menghormati, kejelasan, & arah tindakan — bukan drama berlebihan atau candaan yang tidak pantas.",hint:"Serius + menghormati + arah tindakan, atau dramatis / bercanda?"},
{n:82,type:"mcq",micro:"Kasus: presentasi tanpa slide",q:"Kamu diminta menyampaikan sesuatu selama 3 menit tanpa slide sama sekali. Cara membuatnya tetap jelas & menarik:",options:["Menyerah saja tanpa slide, lalu meminta waktu tambahan untuk menyiapkan tampilan visual terlebih dahulu","Bicara datar dan panjang tanpa struktur, berharap penonton menangkap sendiri inti pembicaraanmu, lalu menyalahkan proyektor yang rusak","Struktur lisan yang kuat (sebut 'tiga hal'), cerita/contoh untuk menggantikan visual, jeda & variasi nada, & mungkin satu properti fisik sederhana"],answer:2,explain:"Tanpa slide, struktur lisan yang jelas & cerita menjadi lebih penting. Banyak pidato terbaik tanpa satu slide pun.",hint:"Struktur lisan + cerita + variasi nada, atau menyerah?"},
{n:83,type:"tf",micro:"Refleksi: presentasi melayani penonton",q:"Benar atau Salah: Presentasi yang baik pada dasarnya adalah tentang membantu penonton memahami atau melakukan sesuatu, bukan tentang menunjukkan seberapa hebat presenternya.",answer:true,explain:"Begitu fokusnya bergeser dari 'apa yang mereka butuhkan' ke 'bagaimana aku terlihat', presentasi biasanya melemah.",hint:"Melayani penonton, atau memamerkan presenter?"},
{n:84,type:"mcq",micro:"Kasus: penonton mengajukan pertanyaan yang keluar topik",q:"Saat tanya jawab, pertanyaan yang melebar jauh dari topik. Respons:",options:["'Pertanyaan menarik, tapi agak di luar fokus hari ini. Boleh kita bahas setelah sesi? Ada pertanyaan lain soal topik utama?'","Menjawab panjang lebar dan mendalam seolah itu bagian dari topik, lalu waktu untuk pertanyaan lain terpakai habis oleh satu orang itu","Mengabaikan penanya dengan kasar & berkata 'itu tidak relevan' lalu langsung memanggil orang berikutnya tanpa menoleh"],answer:0,explain:"Menghargai pertanyaan + mengarahkan kembali ke fokus + menawarkan waktu terpisah menjaga sesi tetap berguna untuk semua.",hint:"Hargai + arahkan kembali + tawarkan waktu lain, atau jawab panjang / abaikan kasar?"},
{n:85,type:"order",micro:"Menyusun pidato singkat yang menggerakkan",q:"Urutkan struktur pidato 2 menit untuk mengajak teman-teman ikut kegiatan sosial.",items:["Buka dengan gambaran/pertanyaan yang membuat mereka peduli","Sampaikan masalahnya secara singkat & satu contoh nyata","Tunjukkan bahwa mereka bisa membantu & caranya mudah","Tutup dengan ajakan konkret & kalimat yang menyemangati"],answer:[0,1,2,3],explain:"Peduli → masalah + contoh → mereka bisa & caranya mudah → ajakan konkret. Pola membujuk yang klasik & efektif.",hint:"Apa yang harus dirasakan penonton sebelum diajak bertindak?"},
{n:86,type:"mcq",micro:"Kasus: kamu kehabisan waktu & penutup terancam",q:"Waktu hampir habis & kamu baru di poin 2 dari 3. Sikap terbaik:",options:["Bicara sangat cepat mencoba memuat semua poin sekaligus dalam sisa waktu, walaupun penonton jadi sulit mengikuti ucapanmu","Lewati atau ringkas poin 3 jadi satu kalimat, & PASTIKAN penutup (rangkuman + ajakan) tetap disampaikan","Terus membahas poin 2 dan 3 sampai tuntas & membiarkan penutup hilang begitu saja, waktu sudah habis"],answer:1,explain:"Penutup adalah bagian yang paling diingat & mengandung ajakan. Lebih baik korbankan poin ketiga daripada penutup.",hint:"Selamatkan penutup, atau kejar semua poin & kehilangan penutup?"},
{n:87,type:"tf",micro:"Kesan pertama beberapa detik",q:"Benar atau Salah: Bagaimana kamu membuka presentasi tidak terlalu berpengaruh; penonton baru menilai presentasi dari keseluruhannya di akhir.",answer:false,explain:"Sebaliknya, penonton cepat memutuskan 'ini menarik / ini membosankan' di detik-detik pertama. Pembuka yang kuat & sikap tenang membeli perhatian mereka.",hint:"Detik-detik pertama menentukan, atau tidak penting?"},
{n:88,type:"mcq",micro:"Kasus: bercerita tentang orang lain",q:"Kamu ingin menceritakan pengalaman temanmu dalam presentasi. Yang bertanggung jawab:",options:["Ceritakan semua detail pribadinya lengkap dengan nama & kejadian tanpa meminta izin, untuk membuat ceritanya terasa nyata bagi penonton","Mengarang cerita seolah-olah itu benar terjadi pada temanmu, untuk membuatnya lebih menarik dan sesuai dengan pesan inti presentasi","Minta izin dulu bila ceritanya pribadi, atau sampaikan tanpa menyebut nama/detail yang mengidentifikasi bila tidak yakin"],answer:2,explain:"Menghormati privasi orang yang kamu ceritakan itu penting. Izin atau anonimkan bila menyangkut hal pribadi.",hint:"Izin / anonimkan, atau umbar tanpa izin / mengarang?"},
{n:89,type:"mcq",micro:"Kasus: presentasi berulang ke audiens berbeda",q:"Kamu membawakan presentasi yang sama ke tiga kelas berbeda. Agar tetap segar & pas:",options:["Sesuaikan contoh & bahasa dengan tiap kelas, perhatikan reaksi tiap audiens, & jangan otomatis membacanya seperti mesin","Bawakan persis sama dari awal sampai akhir tanpa memperhatikan yang ada di depanmu, demi konsisten di tiga kelas yang berbeda-beda","Ubah total isinya tiap kali tampil hingga pesan intinya berbeda-beda, jadi tiap kelas mendapat cerita baru lagi"],answer:0,explain:"Inti tetap; contoh, penekanan, & interaksi menyesuaikan tiap audiens agar tidak terasa kaleng-kaleng.",hint:"Sesuaikan contoh & baca audiens, atau otomatis sama?"},
{n:90,type:"open",micro:"Kasus menyeluruh",q:"Kamu terpilih memberikan sambutan 3 menit di acara perpisahan kelas. Kamu ingin sambutan ini berkesan, tidak klise, dan membuat teman-teman merasa. Rancang: pesan inti, pembuka, isi (termasuk 1 cerita/kenangan spesifik), penutup, dan 3 hal soal penyampaian yang akan kamu perhatikan.",explain:"Jawaban baik memuat: pesan inti yang spesifik dan tidak klise; pembuka dengan kenangan/gambaran konkret (bukan frasa umum); isi dengan minimal satu cerita/kenangan spesifik yang menautkan ke pesan; penutup dengan callback ke pembuka + ajakan/harapan; dan 3 aspek penyampaian konkret (mis. tempo & jeda, kontak mata / kartu poin bukan naskah, mengelola emosi/suara).",hint:"Hindari frasa klise; pakai kenangan spesifik; tautkan ke satu pesan; callback di penutup; sebut 3 hal penyampaian yang konkret.",sample:"PESAN INTI: 'Yang akan kita bawa dari kelas ini bukan nilai rapor, tapi cara kita saling menjaga.' PEMBUKA: 'Tiga tahun lalu, sebagian besar dari kita nggak saling kenal. Aku ingat hari pertama, aku duduk sendirian sampai seseorang — yang sekarang jadi sahabatku — nawarin setengah rotinya.' (kenangan spesifik, bukan 'kita telah melewati banyak hal'). ISI: (1) satu-dua kenangan spesifik lain yang mewakili karakter kelas — misalnya waktu kelas patungan diam-diam buat teman yang keluarganya kesusahan; waktu kalah lomba tapi pulang sambil nyanyi-nyanyi. (2) apa yang kenangan itu tunjukkan: kelas ini istimewa bukan karena berprestasi, tapi karena jarang ada yang dibiarkan sendirian. PENUTUP: 'Kita akan berpencar ke sekolah dan kota yang berbeda. Tapi kalau nanti kalian ketemu anak baru yang duduk sendirian — tawarin setengah roti kalian. Itu cara kita tetap jadi kelas ini. Terima kasih untuk tiga tahun ini.' (callback ke pembuka + ajakan). PENYAMPAIAN yang kuperhatikan: (1) tempo pelan dan jeda setelah kalimat penting supaya emosinya sampai; (2) kontak mata menyapu ke berbagai teman, bukan menunduk ke kertas — aku cuma bawa kartu poin; (3) menjaga suara stabil di bagian yang mengharukan dengan menarik napas sebelum mulai, dan tidak apa-apa kalau sedikit bergetar karena itu tulus."},
{n:91,type:"mcq",micro:"Kasus: menghadapi 'blank' total",q:"Kamu benar-benar lupa & pikiran kosong di panggung. Langkah pemulihan:",options:["Lari dari panggung sambil menahan malu, lalu meminta guru menggantikan presentasimu hari itu juga atau mengulang di lain waktu","Berhenti, tarik napas, lihat kartu/slide, & bila perlu ucapkan jujur 'Sebentar, saya kehilangan alur' lalu lanjut — penonton memahami","Terus bicara ngawur berharap menyambung ke inti, tanpa berhenti atau melihat catatan sedikit pun, sampai waktu habis"],answer:1,explain:"Jeda + melihat catatan + kejujuran singkat jauh lebih baik daripada mengarang atau kabur. Penonton umumnya berempati.",hint:"Jeda + catatan + jujur singkat, atau ngawur / kabur?"},
{n:92,type:"tf",micro:"Refleksi: setiap kesempatan adalah latihan",q:"Benar atau Salah: Menjelaskan sesuatu ke teman, menjawab di kelas, atau bercerita tentang akhir pekanmu adalah kesempatan berlatih keterampilan presentasi & bercerita, bukan hanya saat tampil resmi.",answer:true,explain:"Struktur yang jelas, cerita yang ringkas, & kontak mata bisa dilatih dalam percakapan sehari-hari.",hint:"Hanya latih saat tampil resmi, atau di percakapan biasa juga?"},
{n:93,type:"mcq",micro:"Kasus: menerima kritik atas presentasimu",q:"Setelah tampil, seseorang berkata presentasimu 'terlalu banyak baca slide'. Respons yang membangun:",options:["'Kamu nggak lihat aku sudah berusaha keras? Susah tahu bikin slide sebanyak itu, kamu juga belum tentu bisa, kan?'","Mengabaikan komentar itu dan tak mengubah apa-apa di presentasi berikutnya; menurutmu itu cuma pendapat satu orang saja","'Terima kasih. Kamu benar, aku terlalu bergantung pada slide. Lain kali aku akan pakai poin lebih sedikit & lebih banyak latihan lisan.'"],answer:2,explain:"Menerima umpan balik dengan terbuka + rencana perbaikan konkret adalah cara tercepat berkembang sebagai presenter.",hint:"Terima + rencana perbaikan, atau membela diri / abaikan?"},
{n:94,type:"mcq",micro:"Kasus: menyeimbangkan data & emosi",q:"Presentasi yang bertujuan menggerakkan orang paling kuat bila...",options:["Menggabungkan data yang meyakinkan pikiran DAN cerita/contoh yang menyentuh hati — bukan hanya salah satu","Hanya menyajikan angka dan grafik rumit; pikiran orang hanya digerakkan data, bukan perasaan","Hanya menceritakan kisah mengharukan tanpa data; perasaan penonton yang menentukan tindakan mereka sesudah presentasi selesai"],answer:0,explain:"Data tanpa cerita terasa dingin & terlupakan; cerita tanpa data terasa lemah & mudah dibantah. Keduanya bersama paling kuat.",hint:"Data + cerita, atau salah satu saja?"},
{n:95,type:"tf",micro:"Presentasi bisa dilatih seumur hidup",q:"Benar atau Salah: Setelah cukup berpengalaman, pembicara publik tidak perlu lagi menyiapkan atau berlatih untuk presentasi penting.",answer:false,explain:"Sebaliknya, yang terlihat 'natural' hampir selalu hasil persiapan. Pembicara berpengalaman pun terus menyiapkan, berlatih, & meminta umpan balik.",hint:"Yang berpengalaman berhenti berlatih, atau terus menyiapkan?"},
{n:96,type:"mcq",micro:"Kasus: refleksi setelah presentasi",q:"Cara belajar dari tiap presentasi:",options:["Menyimpulkan bahwa penonton yang salah bila kurang responsif, jadi tak perlu ada yang diubah pada presentasi berikutnya","Segera setelah selesai, catat: apa yang berjalan baik? bagian mana penonton hilang perhatian? apa satu hal yang akan kuubah lain kali?","Tidak mengevaluasi, hanya merasa lega bahwa sudah selesai, lalu melupakan semuanya sampai presentasi berikutnya nanti"],answer:1,explain:"Refleksi jujur & segera (selagi ingatan segar) mengubah tiap presentasi menjadi pelajaran untuk yang berikutnya.",hint:"Evaluasi jujur & segera, atau hanya lega / menyalahkan penonton?"},
{n:97,type:"mcq",micro:"Prinsip inti bab ini",q:"Pesan inti presentasi & bercerita:",options:["Tampilkan sebanyak mungkin informasi di slide penuh teks, lalu bacakan kata per kata untuk memastikan tak ada yang terlewat bagi penonton, dan jangan terlalu memedulikan reaksi mereka; lengkap itu lebih baik","Hafalkan naskah kata per kata lalu bacakan persis tanpa perubahan, tanpa memperhatikan penonton, tanpa cerita, dan tanpa menyesuaikan dengan reaksi mereka selama presentasi; itu terlihat profesional","Tentukan satu pesan inti untuk penonton tertentu; susun pembuka-isi-penutup yang jelas; pakai cerita & contoh untuk membuatnya nyata & melekat; slide sebagai pendukung; latih penyampaian; & sesuaikan dengan reaksi penonton"],answer:2,explain:"Ringkasan: satu pesan + kenal penonton + struktur + cerita + slide pendukung + latihan + membaca ruangan.",hint:"Satu pesan, penonton, struktur, cerita, slide pendukung, latihan, baca ruangan — rangkai."},
{n:98,type:"tf",micro:"Refleksi: kamu adalah presentasi",q:"Benar atau Salah: Pada akhirnya, presenter — suara, energi, kejujuran, & koneksinya dengan penonton — lebih menentukan keberhasilan daripada slide atau alat bantu.",answer:true,explain:"Slide bisa hilang, alat bisa gagal; yang tersisa & paling berkesan adalah bagaimana kamu menyampaikannya.",hint:"Slide yang menentukan, atau presenternya?"},
{n:99,type:"mcq",micro:"Kasus: memulai berlatih presentasi",q:"Cara termudah mulai memperbaiki keterampilan presentasimu:",options:["Ambil satu kesempatan kecil minggu ini (menjawab di kelas, menjelaskan ke kelompok) & sadar melatih satu hal: satu pesan jelas, atau kontak mata, atau tempo tenang","Menunggu sampai ada presentasi besar yang penting, lalu berharap langsung mahir tanpa pernah berlatih dalam kesempatan-kesempatan kecil sebelumnya","Menghindari kesempatan berbicara di depan orang banyak sampai kamu merasa siap dan tidak gugup lagi; latihan baru perlu dimulai setelah itu"],answer:0,explain:"Keterampilan tumbuh dari latihan kecil yang sadar & berulang, bukan dari satu lompatan besar.",hint:"Latih satu hal di kesempatan kecil, atau menunggu / menghindar?"},
{n:100,type:"open",micro:"Refleksi & aturan pribadi presentasi",q:"Tulis 'aturan pribadi presentasi & bercerita' berisi minimal 5 poin yang akan kamu pegang, masing-masing dengan alasan singkat.",explain:"Jawaban baik memuat minimal 5 aturan konkret dengan alasan, mencakup ide inti bab: satu pesan inti + kenal penonton, struktur dengan pembuka-penutup matang, slide poin bukan paragraf + bicara dengan kata sendiri, sisipkan cerita yang ditautkan ke pesan, latihan lisan + umpan balik, penyampaian (kontak mata, jeda, membaca ruangan), tenang saat lupa, refleksi setelahnya.",hint:"Ambil satu pelajaran tiap fase — satu pesan, struktur, slide pendukung, cerita, latihan, penyampaian, refleksi — jadikan aturan 'aku akan...'.",sample:"Contoh aturan pribadi: (1) Sebelum menyiapkan apa pun, aku tetapkan satu pesan inti dan siapa penontonnya — karena semua bagian lain harus melayani itu. (2) Aku susun pembuka-isi-penutup yang jelas, dan aku siapkan pembuka & penutup paling matang — karena itu bagian yang paling diingat penonton. (3) Aku pakai slide berisi poin & visual sederhana, bukan paragraf, dan aku menjelaskan dengan kata-kataku sendiri — karena penonton tidak bisa membaca dan menyimak sekaligus. (4) Aku sisipkan minimal satu cerita atau contoh nyata untuk menguatkan poin terpenting, lalu menautkannya ke pesan — karena cerita jauh lebih mudah diingat daripada daftar fakta. (5) Aku latihan lisan minimal dua-tiga kali dengan timer dan, kalau bisa, di depan satu orang untuk umpan balik — karena 'tahu isinya' berbeda dari 'bisa menyampaikannya'. (6) Saat tampil, aku menatap berbagai penonton, memakai jeda setelah kalimat penting, dan menyesuaikan diri kalau perhatian mereka menurun. (7) Kalau lupa, aku berhenti tenang, lihat kartu poin, lalu lanjut — bukan panik. (8) Setelah selesai, aku catat satu hal yang berjalan baik dan satu yang akan kuubah."},
];
